									: h("button", { style: Object.assign({}, BTN_GHOST, { color: TOKENS.danger, borderColor: "rgba(239,107,115,.35)", padding: "3px 8px", fontSize: "11px" }), onClick: (e) => { e.stopPropagation(); requestDeletePreset(p.id); } }, "删除"),
